package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AllowedScopesM2mVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allowed scopes m 2m of trusted client ")
  void test_allowed_scopes_m_2m_v_o_builder() {
    Assertions.assertFalse(AllowedScopesM2mVO.nullValue().getAllowedScopesM2m().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AllowedScopesM2mVO.tryFrom(null).getAllowedScopesM2m().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        AllowedScopesM2mVO.from("one").getAllowedScopesM2m().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowedScopesM2mVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AllowedScopesM2mVO.from("one").toString());
  }
}
